### Core Data Models & Abstractions

```csharp
namespace HealthcareMonitoring.Models;

public enum AlertSeverity
{
    Warning,
    Critical
}

public record TelemetryPayload(
    string PatientId,
    DateTimeOffset Timestamp,
    double HeartRate, // Beats Per Minute (BPM)
    double SpO2       // Oxygen Saturation (%)
);

public record AnomalyAlert(
    Guid AlertId,
    string PatientId,
    DateTimeOffset Timestamp,
    string Metric,
    double CurrentValue,
    double Mean,
    double StdDev,
    AlertSeverity Severity,
    string Message
);
```

---

### Layer Integration: The Thread-Safe Message Broker

This service serves as the core communication medium, exposing separate write/read endpoints to keep layers fully isolated.

```csharp
using System.Threading.Channels;
using HealthcareMonitoring.Models;

namespace HealthcareMonitoring.Messaging;

public interface IMessageHub
{
    ChannelWriter<TelemetryPayload> TelemetryWriter { get; }
    ChannelReader<TelemetryPayload> TelemetryReader { get; }
    ChannelWriter<AnomalyAlert> AlertWriter { get; }
    ChannelReader<AnomalyAlert> AlertReader { get; }
}

public class MessageHub : IMessageHub
{
    private readonly Channel<TelemetryPayload> _telemetryChannel;
    private readonly Channel<AnomalyAlert> _alertChannel;

    public MessageHub(int capacity = 10000)
    {
        // Unbounded or bounded options with Backpressure handling
        var options = new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleWriter = false,
            SingleReader = true // Processed sequentially/concurrently by our engine
        };

        _telemetryChannel = Channel.CreateBounded<TelemetryPayload>(options);
        _alertChannel = Channel.CreateBounded<AnomalyAlert>(options);
    }

    public ChannelWriter<TelemetryPayload> TelemetryWriter => _telemetryChannel.Writer;
    public ChannelReader<TelemetryPayload> TelemetryReader => _telemetryChannel.Reader;
    public ChannelWriter<AnomalyAlert> AlertWriter => _alertChannel.Writer;
    public ChannelReader<AnomalyAlert> AlertReader => _alertChannel.Reader;
}
```

