### Layer 1: Vital Signs Ingester

Validates clinical telemetry ranges before passing payload to downstream workers.

```csharp
using Microsoft.Extensions.Logging;
using HealthcareMonitoring.Models;
using HealthcareMonitoring.Messaging;

namespace HealthcareMonitoring.Ingestion;

public interface IVitalSignsIngester
{
    ValueTask IngestAsync(TelemetryPayload payload, CancellationToken cancellationToken = default);
}

public class VitalSignsIngester : IVitalSignsIngester
{
    private readonly IMessageHub _messageHub;
    private readonly ILogger<VitalSignsIngester> _logger;

    public VitalSignsIngester(IMessageHub messageHub, ILogger<VitalSignsIngester> logger)
    {
        _messageHub = messageHub;
        _logger = logger;
    }

    public async ValueTask IngestAsync(TelemetryPayload payload, CancellationToken cancellationToken = default)
    {
        if (payload == null) return;

        // Strict clinical range pre-validation to eliminate sensor noise / errors
        if (payload.HeartRate is <= 0 or > 300 || payload.SpO2 is < 0 or > 100)
        {
            _logger.LogWarning("Rejected corrupted telemetry for Patient {PatientId}: HR={HR}, SpO2={SpO2}", 
                payload.PatientId, payload.HeartRate, payload.SpO2);
            return;
        }

        _logger.LogDebug("Ingesting telemetry for Patient {PatientId}: HR={HR} bpm, SpO2={SpO2}%", 
            payload.PatientId, payload.HeartRate, payload.SpO2);

        await _messageHub.TelemetryWriter.WriteAsync(payload, cancellationToken);
    }
}
```

