### Layer 2: Anomaly Detection Engine

Features a thread-safe sliding window. Uses both **absolute safety thresholds** (e.g., immediate critical alert if SpO2 drops below 90%) and **statistical deviation thresholds (Z-Score)** to identify sudden, relative deterioration trends.

```csharp
using System.Collections.Concurrent;
using Microsoft.Extensions.Logging;
using HealthcareMonitoring.Models;
using HealthcareMonitoring.Messaging;

namespace HealthcareMonitoring.Analysis;

public class SlidingWindow
{
    private readonly Queue<double> _history = new();
    private readonly int _maxSize;
    private readonly object _lock = new();

    public SlidingWindow(int maxSize) => _maxSize = maxSize;

    public void Add(double val)
    {
        lock (_lock)
        {
            _history.Enqueue(val);
            if (_history.Count > _maxSize) _history.Dequeue();
        }
    }

    public double[] GetSnapshot()
    {
        lock (_lock) => return _history.ToArray();
    }
}

public class PatientMetricsState
{
    public SlidingWindow HeartRateWindow { get; } = new(15);
    public SlidingWindow SpO2Window { get; } = new(15);
}

public class AnomalyDetectorEngine
{
    private readonly IMessageHub _messageHub;
    private readonly ILogger<AnomalyDetectorEngine> _logger;
    private readonly ConcurrentDictionary<string, PatientMetricsState> _patientStates = new();

    // Configuration limits
    private const double MaxHealthyHR = 130.0;
    private const double MinHealthyHR = 50.0;
    private const double MinCriticalSpO2 = 90.0;
    private const double ZScoreThreshold = 2.5; // Trigger statistical warning on changes > 2.5 StdDev
    private const int MinRequiredSamplesForStats = 5;

    public AnomalyDetectorEngine(IMessageHub messageHub, ILogger<AnomalyDetectorEngine> logger)
    {
        _messageHub = messageHub;
        _logger = logger;
    }

    public async Task StartProcessingAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Anomaly Detection Engine started.");

        try
        {
            await foreach (var telemetry in _messageHub.TelemetryReader.ReadAllAsync(cancellationToken))
            {
                var state = _patientStates.GetOrAdd(telemetry.PatientId, _ => new PatientMetricsState());

                state.HeartRateWindow.Add(telemetry.HeartRate);
                state.SpO2Window.Add(telemetry.SpO2);

                await AnalyzeHeartRateAsync(telemetry, state.HeartRateWindow, cancellationToken);
                await AnalyzeSpO2Async(telemetry, state.SpO2Window, cancellationToken);
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogInformation("Anomaly Detection Engine stopping safely.");
        }
    }

    private async Task AnalyzeHeartRateAsync(TelemetryPayload payload, SlidingWindow window, CancellationToken token)
    {
        double current = payload.HeartRate;

        // 1. Clinical Absolute Limit Check
        if (current > MaxHealthyHR || current < MinHealthyHR)
        {
            var severity = (current > 150 || current < 40) ? AlertSeverity.Critical : AlertSeverity.Warning;
            await PublishAlertAsync(new AnomalyAlert(
                Guid.NewGuid(), payload.PatientId, payload.Timestamp, "HeartRate", current, 0, 0, severity,
                $"Absolute Limit Broken: HR is dangerous ({current} BPM)"
            ), token);
            return;
        }

        // 2. Statistical Volatility Analysis
        var samples = window.GetSnapshot();
        if (samples.Length < MinRequiredSamplesForStats) return;

        var (mean, stdDev) = CalculateStatistics(samples);
        if (stdDev < 1.0) return; // Ignore micro-volatility

        double zScore = Math.Abs(current - mean) / stdDev;
        if (zScore > ZScoreThreshold)
        {
            await PublishAlertAsync(new AnomalyAlert(
                Guid.NewGuid(), payload.PatientId, payload.Timestamp, "HeartRate", current, mean, stdDev,
                AlertSeverity.Warning,
                $"Sudden physiological shift detected! Z-Score: {zScore:F2} (Mean: {mean:F1}, StdDev: {stdDev:F2})"
            ), token);
        }
    }

    private async Task AnalyzeSpO2Async(TelemetryPayload payload, SlidingWindow window, CancellationToken token)
    {
        double current = payload.SpO2;

        // 1. Absolute clinical limits
        if (current < MinCriticalSpO2)
        {
            await PublishAlertAsync(new AnomalyAlert(
                Guid.NewGuid(), payload.PatientId, payload.Timestamp, "SpO2", current, 0, 0,
                AlertSeverity.Critical, $"Hypoxemia Detected: Critical SpO2 levels ({current}%)!"
            ), token);
            return;
        }

        // 2. Statistical Analysis for early respiratory failure warnings
        var samples = window.GetSnapshot();
        if (samples.Length < MinRequiredSamplesForStats) return;

        var (mean, stdDev) = CalculateStatistics(samples);
        if (stdDev < 0.2) return; 

        double zScore = (mean - current) / stdDev; // We care about drops (current is below mean)
        if (zScore > ZScoreThreshold)
        {
            await PublishAlertAsync(new AnomalyAlert(
                Guid.NewGuid(), payload.PatientId, payload.Timestamp, "SpO2", current, mean, stdDev,
                AlertSeverity.Warning, $"Rapid Oxygen desaturation: Z-Score: {zScore:F2} (Mean: {mean:F1}%)"
            ), token);
        }
    }

    private async ValueTask PublishAlertAsync(AnomalyAlert alert, CancellationToken token)
    {
        _logger.LogWarning("[Anomaly Flags] Patient: {PatientId} | {Metric}: {CurrentValue} | {Message}", 
            alert.PatientId, alert.Metric, alert.CurrentValue, alert.Message);

        await _messageHub.AlertWriter.WriteAsync(alert, token);
    }

    private static (double Mean, double StdDev) CalculateStatistics(double[] values)
    {
        double mean = values.Average();
        double sumOfSquares = values.Sum(v => Math.Pow(v - mean, 2));
        double stdDev = Math.Sqrt(sumOfSquares / values.Length);
        return (mean, stdDev);
    }
}
