### Layer 3: Emergency Dispatch Subsystem

Dispatches notifications via virtual external interfaces. Implements robust **exponential backoff with jitter** to guarantee resilience against transient failures.

```csharp
using Microsoft.Extensions.Logging;
using HealthcareMonitoring.Models;
using HealthcareMonitoring.Messaging;

namespace HealthcareMonitoring.Dispatch;

public interface ISmsGateway { Task SendSmsAsync(string recipient, string message); }
public interface IEmailGateway { Task SendEmailAsync(string recipient, string subject, string body); }

public class EmergencyDispatcher
{
    private readonly IMessageHub _messageHub;
    private readonly ISmsGateway _smsGateway;
    private readonly IEmailGateway _emailGateway;
    private readonly ILogger<EmergencyDispatcher> _logger;
    private readonly Random _jitterGenerator = new();

    public EmergencyDispatcher(
        IMessageHub messageHub, 
        ISmsGateway smsGateway, 
        IEmailGateway emailGateway, 
        ILogger<EmergencyDispatcher> logger)
    {
        _messageHub = messageHub;
        _smsGateway = smsGateway;
        _emailGateway = emailGateway;
        _logger = logger;
    }

    public async Task StartProcessingAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Emergency Dispatch Subsystem online.");

        try
        {
            await foreach (var alert in _messageHub.AlertReader.ReadAllAsync(cancellationToken))
            {
                // Dispatches critical alerts with high priority, warning alerts with standard routing
                await DispatchWithRetryAsync(alert, cancellationToken);
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogInformation("Emergency Dispatch Subsystem offline.");
        }
    }

    private async Task DispatchWithRetryAsync(AnomalyAlert alert, CancellationToken token)
    {
        int maxRetryAttempts = 3;
        double baseIntervalSeconds = 1.0;

        string dispatchMsg = $"[PRIORITY:{alert.Severity.ToString().ToUpper()}] Patient {alert.PatientId} is unstable! {alert.Metric} is {alert.CurrentValue}. {alert.Message}";

        for (int attempt = 1; attempt <= maxRetryAttempts; attempt++)
        {
            try
            {
                token.ThrowIfCancellationRequested();

                // Dispatch to multiple channels in parallel
                var tasks = new List<Task>
                {
                    _smsGateway.SendSmsAsync("On-Call Physician (+1-555-0199)", dispatchMsg),
                    _emailGateway.SendEmailAsync("trauma-unit@hospital.org", $"EMERGENCY ALERT: {alert.PatientId}", dispatchMsg)
                };

                await Task.WhenAll(tasks);
                _logger.LogInformation("Successfully dispatched notification for {PatientId} on attempt #{Attempt}.", alert.PatientId, attempt);
                return; 
            }
            catch (Exception ex) when (attempt < maxRetryAttempts)
            {
                // Calculate exponential backoff with random jitter to prevent "thundering herd" gateway overloading
                double delaySec = (Math.Pow(2, attempt) * baseIntervalSeconds) + (_jitterGenerator.NextDouble() * 0.5);

                _logger.LogWarning(ex, "Dispatch attempt #{Attempt} failed for alert {AlertId}. Retrying in {Delay:F2}s...", 
                    attempt, alert.AlertId, delaySec);

                await Task.Delay(TimeSpan.FromSeconds(delaySec), token);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "CRITICAL EXCEPTION: Failed to dispatch emergency alerts for Patient {PatientId} after max retries.", alert.PatientId);
            }
        }
    }
}
