### External Services & Mock Network Gateways

```csharp
using Microsoft.Extensions.Logging;

namespace HealthcareMonitoring.Infrastructure;

public class MockSmsGateway : Dispatch.ISmsGateway
{
    private readonly ILogger<MockSmsGateway> _logger;
    private int _failCounter = 0;

    public MockSmsGateway(ILogger<MockSmsGateway> logger) => _logger = logger;

    public async Task SendSmsAsync(string recipient, string message)
    {
        await Task.Delay(50); // Simulating network latency

        // Intentionally simulate a transient failure every 3rd call to verify dispatcher's resilience
        if (Interlocked.Increment(ref _failCounter) % 3 == 0)
        {
            throw new HttpRequestException("SMS Gateway Carrier Timeout (Mocked Transient Failure)");
        }

        _logger.LogInformation("📱 SMS Dispatched to {Recipient}: \"{Msg}\"", recipient, message);
    }
}

public class MockEmailGateway : Dispatch.IEmailGateway
{
    private readonly ILogger<MockEmailGateway> _logger;

    public MockEmailGateway(ILogger<MockEmailGateway> logger) => _logger = logger;

    public async Task SendEmailAsync(string recipient, string subject, string body)
    {
        await Task.Delay(80); // Network latency simulation
        _logger.LogInformation("✉️ Email sent to <{Recipient}> | Subject: '{Subject}'", recipient, subject);
    }
}
