### Harness System Simulation (Console App)

Let's test this system using a `Program.cs` file that boots our isolated layers and streams continuous test scenarios to simulate:
1. **Patient A**: A perfectly stable recovery.
2. **Patient B**: Sudden progressive cardiac failure (rapidly raising Heart Rate).
3. **Patient C**: Rapid respiratory desaturation (acute SpO2 drop).

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using HealthcareMonitoring.Messaging;
using HealthcareMonitoring.Ingestion;
using HealthcareMonitoring.Analysis;
using HealthcareMonitoring.Dispatch;
using HealthcareMonitoring.Infrastructure;
using HealthcareMonitoring.Models;

namespace HealthcareMonitoring;

public class Program
{
    public static async Task Main(string[] args)
    {
        // 1. Dependency Injection Configuration
        var services = new ServiceCollection()
            .AddLogging(configure => configure
                .AddConsole()
                .SetMinimumLevel(LogLevel.Information))
            .AddSingleton<IMessageHub, MessageHub>()
            .AddSingleton<IVitalSignsIngester, VitalSignsIngester>()
            .AddSingleton<ISmsGateway, MockSmsGateway>()
            .AddSingleton<IEmailGateway, MockEmailGateway>()
            .AddSingleton<AnomalyDetectorEngine>()
            .AddSingleton<EmergencyDispatcher>()
            .BuildServiceProvider();

        using var cts = new CancellationTokenSource();

        var logger = services.GetRequiredService<ILogger<Program>>();
        var ingester = services.GetRequiredService<IVitalSignsIngester>();
        var detector = services.GetRequiredService<AnomalyDetectorEngine>();
        var dispatcher = services.GetRequiredService<EmergencyDispatcher>();

        logger.LogInformation("Initialising ICU Patient Monitoring Pipeline...");

        // 2. Start Background Pipelines (Layers 2 & 3 Consumers)
        var detectorTask = Task.Run(() => detector.StartProcessingAsync(cts.Token));
        var dispatcherTask = Task.Run(() => dispatcher.StartProcessingAsync(cts.Token));

        // 3. Begin Multi-Patient Telemetry Simulators
        var simTasks = new List<Task>
        {
            SimulateNormalPatientAsync(ingester, cts.Token),
            SimulateCardiacArrestPatientAsync(ingester, cts.Token),
            SimulateRespiratoryFailurePatientAsync(ingester, cts.Token)
        };

        logger.LogInformation("Monitoring Active. Realtime patient telemetry processing on-the-fly.");
        logger.LogInformation("Press [ENTER] to terminate the monitoring simulation safely.");

        Console.ReadLine();

        logger.LogWarning("System Shutdown triggered. Cleaning channels, flushing dispatchers...");
        cts.Cancel();

        try
        {
            await Task.WhenAll(simTasks);
            await Task.WhenAll(detectorTask, dispatcherTask);
        }
        catch (Exception ex) when (ex is OperationCanceledException or AggregateException)
        {
            // Expected safe cancellation 
        }

        logger.LogInformation("All patient monitoring services terminated cleanly.");
    }

    private static async Task SimulateNormalPatientAsync(IVitalSignsIngester ingester, CancellationToken token)
    {
        var random = new Random();
        while (!token.IsCancellationRequested)
        {
            // Patient 1: Stable vitals with standard healthy noise
            var payload = new TelemetryPayload(
                PatientId: "PATIENT-A (Normal)",
                Timestamp: DateTimeOffset.UtcNow,
                HeartRate: random.Next(72, 78),
                SpO2: random.Next(97, 100)
            );

            await ingester.IngestAsync(payload, token);
            await Task.Delay(1000, token); // Normal rate
        }
    }

    private static async Task SimulateCardiacArrestPatientAsync(IVitalSignsIngester ingester, CancellationToken token)
    {
        double currentHR = 75;
        while (!token.IsCancellationRequested)
        {
            // Patient 2: Progressive severe tachycardia ending in flatlining
            currentHR += 10.5; // High jump
            if (currentHR > 170) currentHR = 35; // Drops severely simulating shock

            var payload = new TelemetryPayload(
                PatientId: "PATIENT-B (Cardiac)",
                Timestamp: DateTimeOffset.UtcNow,
                HeartRate: currentHR,
                SpO2: 96
            );

            await ingester.IngestAsync(payload, token);
            await Task.Delay(1200, token);
        }
    }

    private static async Task SimulateRespiratoryFailurePatientAsync(IVitalSignsIngester ingester, CancellationToken token)
    {
        double currentSpO2 = 98.0;
        while (!token.IsCancellationRequested)
        {
            // Patient 3: Fast progressive hypoxemic deterioration
            currentSpO2 -= 1.8;

            var payload = new TelemetryPayload(
                PatientId: "PATIENT-C (Respiratory)",
                Timestamp: DateTimeOffset.UtcNow,
                HeartRate: 85,
                SpO2: Math.Clamp(currentSpO2, 70, 100)
            );

            await ingester.IngestAsync(payload, token);
            await Task.Delay(1500, token);
        }
    }
}
